/* Read-only: same ordered pre-migration projection on both schemas. */
SET NOCOUNT ON;
SELECT 'DatSan' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaDatSan],[MaKH],[MaSan],[MaKhungGio],[NgayChoi],[ThoiLuong],[DonGia],[TienSan],[TienDichVu],[MaKM],[TienGiam],[TongTien],[NgayDat],[MaNV],[TrangThai],[GhiChu],[GioBatDau],[GioKetThuc],[CheDoGia],[HinhThucDat] FROM dbo.[DatSan] ORDER BY [MaDatSan] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[DatSan];
SELECT 'HoaDon' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaHoaDon],[MaDatSan],[MaTKLap],[TienSan],[TienDichVu],[TienGiam],[TongTien],[DaThanhToan],[TrangThai],[DaChot],[NgayLap],[ConLai],[HoanTatTaiChinh] FROM dbo.[HoaDon] ORDER BY [MaHoaDon] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[HoaDon];
SELECT 'ChiTietDichVu' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaDatSan],[MaDV],[SoLuong],[DonGia],[ThanhTien],[NgayGhiNhan],[MaNV],[MaChiTiet],[Nguon],[QuyCach],[SoDonViMoiQuyCach],[DonGiaDonViSnapshot] FROM dbo.[ChiTietDichVu] ORDER BY [MaChiTiet] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[ChiTietDichVu];
SELECT 'ThanhToan' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaTT],[MaDatSan],[NgayThanhToan],[SoTien],[PhuongThuc],[MaGiaoDich],[TrangThai],[MaNV] FROM dbo.[ThanhToan] ORDER BY [MaTT] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[ThanhToan];
SELECT 'HoanTien' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaHT],[MaTT],[MaHuy],[NgayHoan],[SoTienHoan],[PhuongThuc],[TrangThai],[MaNV],[NgayXacNhan],[LyDo] FROM dbo.[HoanTien] ORDER BY [MaHT] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[HoanTien];
SELECT 'HuyDatSan' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaHuy],[MaDatSan],[NgayHuy],[LyDo],[NguoiHuy],[TiLeHoan],[SoTienHoan],[SoTienThucThuSnapshot] FROM dbo.[HuyDatSan] ORDER BY [MaHuy] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[HuyDatSan];
SELECT 'XacNhanSan' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaXacNhan],[MaDatSan],[MaNV],[ThoiGianNhan],[ThoiGianKetThuc],[TinhTrangSan],[GhiChu] FROM dbo.[XacNhanSan] ORDER BY [MaXacNhan] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[XacNhanSan];
SELECT 'DichVu' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaDV],[TenDV],[DonViTinh],[DonGia],[TrangThai],[HoTroLoc] FROM dbo.[DichVu] ORDER BY [MaDV] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[DichVu];
SELECT 'GiaTheoCa' AS tableName,COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT [MaCa],[GioBatDau],[GioKetThuc],[DonGia] FROM dbo.[GiaTheoCa] ORDER BY [MaCa] FOR JSON PATH,INCLUDE_NULL_VALUES)),2) AS sha256 FROM dbo.[GiaTheoCa];
